import sys

def decompose_segment(L, R):
    result = []
    current_level = 0
    while L <= R:
        segment_length = 10 ** (2 ** current_level)
        if L + segment_length - 1 > R:
            segment_length = R - L + 1
        count = (R - L + 1) // segment_length
        if (R - L + 1) % segment_length != 0:
